<template><section class="rounded-lg border border-slate-200 bg-white p-4 overflow-x-auto"><h3 class="font-bold text-slate-900">{{ title }}</h3><table class="mt-3 w-full"><thead><tr><th>Document</th><th>Employé</th><th v-if="period">Période</th><th>Date</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.titre || item.nom_original }}</strong><p class="text-xs text-slate-500">{{ item.nom_original }}</p></td><td>{{ item.employe ? `${item.employe.prenom} ${item.employe.nom}` : 'Document général' }}</td><td v-if="period">{{ item.periode }}</td><td>{{ new Date(item.created_at).toLocaleDateString('fr-FR') }}</td><td class="text-right"><button class="text-blue-700" @click="$emit('download', item)">Télécharger</button></td></tr><tr v-if="!items.length"><td :colspan="period ? 5 : 4" class="py-8 text-center text-sm text-slate-400">Aucun fichier disponible.</td></tr></tbody></table></section></template>
<script setup>defineProps({ title: String, items: { type: Array, default: () => [] }, period: Boolean }); defineEmits(['download'])</script>
<style scoped>th{@apply whitespace-nowrap bg-slate-50 px-3 py-2 text-left text-xs uppercase text-slate-500}td{@apply whitespace-nowrap border-t border-slate-100 px-3 py-2 text-sm text-slate-700}</style>
